47	impl<'a> Formatter<'a> {
48	    pub fn new(allocator: &'a Allocator, options: FormatOptions) -> Self {
49	        Self { allocator, options }
50	    }
51	
52	    /// Formats the given AST `Program` and returns the formatted string.
53	    pub fn build(self, program: &Program<'a>) -> String {
54	        let formatted = self.format(program);
55	        formatted.print().unwrap().into_code()
56	    }
57	
58	    #[inline]
59	    pub fn format(self, program: &'a Program<'a>) -> Formatted<'a> {
60	        self.format_with_external_callbacks(program, None)
61	    }
62	
63	    #[inline]
64	    pub fn format_with_external_callbacks(
65	        self,
66	        program: &'a Program<'a>,
67	        external_callbacks: Option<ExternalCallbacks>,
68	    ) -> Formatted<'a> {
69	        let program_node = AstNode::new(program, AstNodes::Dummy(), self.allocator);
70	
71	        let context = FormatContext::new(
72	            program.source_text,
73	            program.source_type,
74	            &program.comments,
75	            self.allocator,
76	            self.options,
77	            external_callbacks,
78	        );
79	
80	        formatter::format(
81	            context,
82	            formatter::Arguments::new(&[formatter::Argument::new(&program_node)]),
83	        )
84	    }
85	
86	    /// Formats an arbitrary value that implements `Format` and returns the `Formatted` IR.
87	    ///
88	    /// Unlike `format()` which requires a full `Program`,
89	    /// this method accepts any value that implements `Format`.
90	    /// This enables fragment formatting for embedded contexts like:
91	    /// - Vue: `v-for`, `v-slot`, and `<script generic="...">`
92	    /// - etc...
93	    ///
94	    /// `SortImportsTransform` is skipped since it only applies to whole `Program` formatting.
95	    pub fn format_node<F: formatter::Format<'a>>(
96	        self,
97	        node: &F,
98	        source_text: &'a str,
99	        source_type: SourceType,
100	        comments: &'a [Comment],
101	        external_callbacks: Option<ExternalCallbacks>,
102	    ) -> Formatted<'a> {
103	        let context = FormatContext::new(
104	            source_text,
105	            source_type,
106	            comments,
107	            self.allocator,
108	            self.options,
109	            external_callbacks,
110	        );
111	        formatter::format(context, formatter::Arguments::new(&[formatter::Argument::new(node)]))
112	    }
113	}
