use std::{fs, path::Path};

use oxc_allocator::Allocator;
use oxc_formatter::{
    FormatOptions, Formatter, JsdocOptions, SortImportsOptions, SortOrder, default_groups,
    default_internal_patterns, get_parse_options,
};
use oxc_parser::Parser;
use oxc_span::SourceType;
use pico_args::Arguments;

fn main() -> Result<(), String> {
    let mut args = Arguments::from_env();
    let name = args.free_from_str().unwrap_or_else(|_| "test.js".to_string());

    let sort_imports_options = SortImportsOptions {
        order: SortOrder::Asc,
        partition_by_newline: false,
        partition_by_comment: false,
        sort_side_effects: false,
        ignore_case: true,
        newlines_between: true,
        internal_pattern: default_internal_patterns(),
        groups: default_groups(),
        custom_groups: vec![],
        newline_boundary_overrides: vec![],
    };

    let path = Path::new(&name);
    let source_text = fs::read_to_string(path).map_err(|_| format!("Missing '{name}'"))?;
    let source_type = SourceType::from_path(path).unwrap();
    let allocator = Allocator::new();

    let ret = Parser::new(&allocator, &source_text, source_type)
        .with_options(get_parse_options())
        .parse();

    let options = FormatOptions {
        sort_imports: Some(sort_imports_options),
        jsdoc: Some(JsdocOptions::default()),
        ..Default::default()
    };

    let formatter = Formatter::new(&allocator, options);
    let code = formatter.build(&ret.program);
    println!("{code}");
    Ok(())
}
