13	#[derive(Debug)]
14	pub enum SourceLine<'a> {
15	    /// Line that contains an import statement.
16	    /// May have leading comments like `/* ... */ import ...`.
17	    /// And also may have trailing comments like `import ...; // ...`.
18	    /// Never be a boundary.
19	    Import(Range<usize>, ImportLineMetadata<'a>),
20	    /// Empty line.
21	    /// May be used as a boundary if `options.partition_by_newline` is true.
22	    Empty,
23	    /// Line that contains only comment(s).
24	    /// May be used as a boundary if `options.partition_by_comment` is true.
25	    CommentOnly(Range<usize>, LineMode),
26	}
27	
28	impl<'a> SourceLine<'a> {
29	    pub fn from_element_range(
30	        elements: &[FormatElement<'a>],
31	        range: Range<usize>,
32	        line_mode: LineMode,
33	    ) -> Self {
34	        debug_assert!(
35	            !range.is_empty(),
36	            "`range` must not be empty, otherwise use `SourceLine::Empty` directly."
37	        );
38	
39	        // Check if the line is comment-only.
40	        // e.g.
41	        // ```text
42	        // // comment
43	        // /* comment */
44	        // /* comment */ // comment
45	        // /* comment */ /* comment */
46	        // ```
47	        let is_comment_only = range.clone().all(|idx| match &elements[idx] {
48	            FormatElement::Text { text, width: _ } => {
49	                text.starts_with("//") || text.starts_with("/*")
50	            }
51	            FormatElement::Line(LineMode::Soft | LineMode::SoftOrSpace) | FormatElement::Space => {
52	                true
53	            }
54	            _ => false,
55	        });
56	        if is_comment_only {
57	            return SourceLine::CommentOnly(range, line_mode);
58	        }
59	
60	        // Check if the line contains an import statement.
61	        // Sometimes, there might be leading comments in the same line,
62	        // so we need to check all elements in the line to find an `ImportDeclaration`.
63	        // ```text
64	        // /* THIS */ import ...
65	        // import ...
66	        // ```
67	        let mut has_import = false;
68	        let mut source = None;
69	        let mut is_side_effect = true;
70	        let mut is_type_import = false;
71	        let mut has_default_specifier = false;
72	        let mut has_namespace_specifier = false;
73	        let mut has_named_specifier = false;
74	
75	        for idx in range.clone() {
76	            let element = &elements[idx];
77	
78	            // Special marker for `ImportDeclaration`
79	            if let FormatElement::Tag(Tag::StartLabelled(id)) = element {
80	                if *id == LabelId::of(JsLabels::ImportDeclaration) {
81	                    has_import = true;
82	                }
83	                continue;
84	            }
85	            if !has_import {
86	                continue;
87	            }
88	
89	            match element {
90	                FormatElement::Token { text } => match *text {
91	                    "import" => {
92	                        // Look ahead to determine import type (skip spaces)
93	                        // Continue scanning to find all specifier types (default, namespace, named)
94	                        let mut offset = 1;
95	                        let mut first_token = true; // Track if this is the first token after "import"
96	                        while idx + offset < elements.len() {
97	                            if matches!(elements[idx + offset], FormatElement::Space) {
98	                                offset += 1;
99	                                continue;
100	                            }
101	
102	                            match &elements[idx + offset] {
103	                                FormatElement::Token { text } => match *text {
104	                                    "type" if first_token => is_type_import = true,
105	                                    "*" => has_namespace_specifier = true,
106	                                    "{" => has_named_specifier = true,
107	                                    "from" => break, // Stop when we reach "from"
108	                                    _ => {}
109	                                },
110	                                FormatElement::Text { .. } => {
111	                                    has_default_specifier = true;
112	                                }
113	                                _ => {}
114	                            }
115	                            first_token = false;
116	                            offset += 1;
117	                        }
118	                    }
119	                    "from" => {
120	                        is_side_effect = false;
121	                        source = None;
122	                    }
123	                    _ => {}
124	                },
125	                FormatElement::Text { text, .. } if source.is_none() => {
126	                    source = Some(text);
127	                }
128	                _ => {}
129	            }
130	        }
131	
132	        SourceLine::Import(
133	            range,
134	            ImportLineMetadata {
135	                // The chunk only contains non-suppressed `ImportDeclaration`s,
136	                // their surrounding comments, and line breaks,
137	                // (= suppressed imports are filtered out by the caller)
138	                // so a non-comment-only line is guaranteed to be an import with a source.
139	                source: source.expect("`ImportDeclaration` must have a source"),
140	                is_side_effect,
141	                is_type_import,
142	                has_default_specifier,
143	                has_namespace_specifier,
144	                has_named_specifier,
145	            },
146	        )
147	    }
148	
149	    pub fn write(
150	        &self,
151	        prev_elements: &[FormatElement<'a>],
152	        next_elements: &mut ArenaVec<'a, FormatElement<'a>>,
153	        preserve_empty_line: bool,
154	    ) {
155	        match self {
156	            SourceLine::Empty => {
157	                // Skip empty lines unless they should be preserved
158	                if preserve_empty_line {
159	                    next_elements.push(FormatElement::Line(LineMode::Empty));
160	                }
161	            }
162	            SourceLine::Import(range, _) => {
163	                for idx in range.clone() {
164	                    next_elements.push(prev_elements[idx].clone());
165	                }
166	                // Always use hard line break after import statement.
167	                next_elements.push(FormatElement::Line(LineMode::Hard));
168	            }
169	            SourceLine::CommentOnly(range, mode) => {
170	                for idx in range.clone() {
171	                    next_elements.push(prev_elements[idx].clone());
172	                }
173	                next_elements.push(FormatElement::Line(*mode));
174	            }
175	        }
176	    }
177	}
