11	/// Parse an `@import` tag's comment text into its components.
12	///
13	/// Handles these forms:
14	/// - `Default, {Named1, Named2} from "module"`
15	/// - `{Named1} from 'module'`
16	/// - `Default from "module"`
17	fn parse_import_tag(comment_text: &str) -> Option<ImportInfo> {
18	    // Normalize: join lines, collapse whitespace
19	    let text: String = join_iter(comment_text.lines().map(str::trim), " ");
20	    let text = text.trim();
21	
22	    // Find "from" keyword followed by a quoted string
23	    let from_idx = text.rfind(" from ")?;
24	    let specifier = text[..from_idx].trim();
25	    let module_part = text[from_idx + 6..].trim();
26	
27	    // Extract module path (strip matching quotes)
28	    let quote = match module_part.as_bytes().first() {
29	        Some(b'"' | b'\'') => module_part.as_bytes()[0] as char,
30	        _ => return None,
31	    };
32	    let module_path = module_part.strip_prefix(quote)?.strip_suffix(quote)?;
33	    if module_path.is_empty() {
34	        return None;
35	    }
36	
37	    // Parse specifier: "Default, {Named1, Named2}", "{Named1}", or "Default"
38	    let (default_import, named_imports) = if let Some(brace_start) = specifier.find('{') {
39	        let brace_end = specifier.rfind('}')?;
40	        let default_part = specifier[..brace_start].trim().trim_end_matches(',').trim();
41	        let named_part = &specifier[brace_start + 1..brace_end];
42	
43	        let default_import =
44	            if default_part.is_empty() { None } else { Some(default_part.to_string()) };
45	
46	        let named_imports: Vec<String> = named_part
47	            .split(',')
48	            .map(|s| {
49	                // Normalize whitespace: "B  as  B1" → "B as B1"
50	                join_iter(s.split_whitespace(), " ")
51	            })
52	            .filter(|s| !s.is_empty())
53	            .collect();
54	
55	        (default_import, named_imports)
56	    } else {
57	        // No braces — just a default import
58	        let name = join_iter(specifier.split_whitespace(), " ");
59	        (Some(name), Vec::new())
60	    };
61	
62	    Some(ImportInfo { default_import, named_imports, module_path: module_path.to_string() })
63	}
