77	/// `"B as B1"` → `"B1"`, `"B2"` → `"B2"`.
78	fn import_specifier_sort_key(specifier: &str) -> &str {
79	    if let Some(idx) = specifier.find(" as ") {
80	        specifier[idx + 4..].trim()
81	    } else {
82	        specifier.trim()
83	    }
