86	/// Merge `@import` tags that share the same module path.
87	/// Returns merged imports sorted by module path (third-party before relative).
88	fn merge_and_sort_imports(imports: Vec<ImportInfo>) -> Vec<ImportInfo> {
89	    if imports.is_empty() {
90	        return imports;
91	    }
92	
93	    // Group by module path (preserving insertion order)
94	    let mut groups: Vec<ImportInfo> = Vec::new();
95	
96	    for import in imports {
97	        if let Some(existing) = groups.iter_mut().find(|g| g.module_path == import.module_path) {
98	            // Merge: take last default import, combine named imports
99	            if import.default_import.is_some() {
100	                existing.default_import = import.default_import;
101	            }
102	            for named in import.named_imports {
103	                // Deduplicate by original import name
104	                let key = import_specifier_sort_key(&named);
105	                let already_exists =
106	                    existing.named_imports.iter().any(|n| import_specifier_sort_key(n) == key);
107	                if !already_exists {
108	                    existing.named_imports.push(named);
109	                }
110	            }
111	        } else {
112	            groups.push(import);
113	        }
114	    }
115	
116	    // Sort named imports within each group by original import name (case-insensitive)
117	    for import in &mut groups {
118	        import.named_imports.sort_by(|a, b| {
119	            cmp_ascii_case_insensitive(import_specifier_sort_key(a), import_specifier_sort_key(b))
120	        });
121	    }
122	
123	    // Sort groups: third-party (no ./ or ../) before relative, then alphabetically
124	    groups.sort_by(|a, b| {
125	        let a_relative = a.module_path.starts_with('.');
126	        let b_relative = b.module_path.starts_with('.');
127	        match (a_relative, b_relative) {
128	            (false, true) => std::cmp::Ordering::Less,
129	            (true, false) => std::cmp::Ordering::Greater,
130	            _ => cmp_ascii_case_insensitive(&a.module_path, &b.module_path),
131	        }
132	    });
133	
134	    groups
135	}
